prompt:
You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

We assume an integer alphabet $\Sigma = \{1, 2, \ldots, \sigma\}$ with $\sigma$ \emph{characters}. A \emph{string} $Y$ is a sequence of characters numbered from $1$ to $n = |Y|$. By $Y[i]$ we denote the $i$-th symbol of $Y$. For a string $Y$ of length $n$, we denote its \emph{reverse} $Y[n] Y[n-1] \ldots Y[1]$ by $\rev{Y}$. We define $Y[i \dd j]$ to be equal to $Y[i] \dots Y[j]$ which we call a \emph{fragment} of $Y$ if $i \le j$ and to the empty string $\eps$ otherwise. We also use notations $Y[i \dd j)$ and $Y(i\dd j]$ which naturally stand for $Y[i] \dots Y[j-1]$ and $Y[i+1] \dots Y[j]$, respectively. 
We call a fragment $Y[1] \dots Y[j]$ \emph{a prefix} of $Y$ and use a simplified notation $Y[\dd i]$, and a fragment $Y[i] \dots Y[n]$ \emph{a suffix} of $Y$ denoted by $Y[i \dd]$.

We say that a fragment $X[i\dd i+\ell)$ is a \emph{previous factor} if 
$X[i\dd i+\ell)=X[i'\dd i'+\ell)$ holds for some $i'\in [1\dd i)$.
The \emph{LZ77 factorization} of $X$ is a factorization $X=F_1\cdots F_z$ into non-empty \emph{phrases}
such tht the $j$th phrase $F_j$ is the longest previous factor starting at position $1+|F_1\cdots F_{j-1}|$; if no previous factor starts there, then $F_j$ consists of a single character.
In the underlying \emph{LZ77 representation}, every phrase $F_j=T[j\dd j+\ell)$ that is a previous fragment is encoded as $(i',\ell)$, where $i'\in [1\dd i)$ satisfies $X[i\dd i+\ell)=X[i'\dd i'+\ell)$.
The remaining length-1 phrases are represented by the underlying character.
We use $\LZ(X)$ to denote the underlying \emph{LZ77 representation} 
and $|\LZ(X)|$ to denote its size (the number of phrases).

The \emph{edit distance} $\ed(X, Y)$ between two strings $X$ and $Y$ is defined as the smallest number of character insertions, deletions, and substitutions required to transform $X$ to $Y$.

\begin{definition}
  A sequence $(x_t,y_t)_{t=1}^m$ is an \emph{alignment}
  of $X,Y\in \Sigma^*$ if $(x_1,y_1)=(1,1)$,
  $(x_m,y_m)=(|X|+1,|Y|+1)$, and $(x_{t+1},y_{t+1})\in \{(x_t+1,y_t+1),(x_t+1,y_t),(x_t,y_t+1)\}$ for $t\in [1\dd m)$.\footnote{This definition is rather complex, but it is equivalent to the standard definition given in the textbooks. We chose this particular formulation as it allowed us to introduce notions essential for this work in a rigorous way.}
\end{definition}
Given an alignment $\A = (x_t,y_t)_{t=1}^m$ of strings $X,Y\in \Sigma^*$,
for every $t\in [1\dd m)$:
\begin{itemize}
  \item If $(x_{t+1},y_{t+1})=(x_t+1,y_t)$, we say that $\A$ \emph{deletes} $X[x_t]$,
  \item If $(x_{t+1},y_{t+1})=(x_t,y_t+1)$, we say that $\A$ \emph{deletes} $Y[y_t]$,
  \item If $(x_{t+1},y_{t+1})=(x_t+1,y_t+1)$, we say that $\A$ \emph{aligns} $X[x_t]$ and $Y[y_t]$, denoted $X[x_t] \sim_\A Y[y_t]$. If~additionally $X[x_t]= Y[y_t]$, we say that $\A$ \emph{matches} $X[x_t]$ and $Y[y_t]$, denoted $X[x_t] \simeq_\A Y[y_t]$.
  Otherwise, we say that $\A$ \emph{substitutes} $X[x_t]$ for $Y[y_t]$.
\end{itemize}

The \emph{cost} of an edit distance alignment $\A$ is the total number characters that $\A$ deletes or substitutes.
We denote the cost by $\cost_{X,Y}(\A)$, omitting the subscript if $X,Y$ are clear from context.

Given an alignment $\A=(x_t,y_t)_{t=1}^m$ of $X,Y\in \Sigma^+$, we partition the elements $(x_t,y_t)$ of $\A$
into \emph{matches} (for which $X[x_t]\simeq_{\A} Y[y_t]$) and \emph{breakpoints} (the remaining elements).
We denote the set of matches and breakpoints by $\mtch_{X,Y}(\A)$ and $\brkp_{X,Y}(\A)$, respectively,
omitting the subscripts if the strings $X,Y$ are clear from context.

We call $M\sub [1\dd |X|]\times [1\dd |Y|]$ a \emph{non-crossing matching} of $X,Y\in \Sigma^*$
if $X[x]=Y[y]$ holds for all $(x,y)\in M$ and there are no distinct pairs $(x,y),(x',y')\in M$ with $x\le x'$ and $y\ge y'$.

Our data structure can be constructed not only from $\LZ(X)$,
but from any \emph{LZ-like representation} describing a factorization $X=F_1\cdots F_f$ into non-empty phrases such that each phrase $F_j$ with $|F_j|>1$ is a previous factor (unlike LZ77, the phrases do not need to be a maximal).

\begin{proposition}\label{prp:RLSLP}
    In the $w$-bit word RAM model, every string $X\in \Sigma^n$ satisfying $w = \Omega(\log n + \log |\Sigma|)$, $z = |\LZ(X)|$, and $\rev{z}=|\LZ(\rev{X})|$ has a representation $\CR(X)$ that uses 
 $\Oh(z \log^2 n)$ space and supports the following queries:
    \begin{enumerate}[label=\textrm{(\alph*)}]
        \item retrieve $n=|X|$, in $\Oh(1)$ time;\label{it:length}
        \item given $i\in [1\dd n]$, retrieve $X[i]$, in $\Oh(\log n)$ time;\label{it:access}
        \item given $i,j\in [1\dd n]$, compute $\LCE(X[i\dd n],X[j\dd n])$, in $\Oh(\log n)$ time;\label{it:lce}
        \item given $i,j\in [1\dd n]$, compute $\LCE(\rev{X}[i\dd n],\rev{X}[j\dd n])$, in $\Oh(\log n)$ time;\label{it:rlce}
        \item compute $\LZ(X)$, in $\Oh(z\log^4 n)$ time;\label{it:lz}
        \item compute $\LZ(\rev{X})$, in $\Oh(\rev{z}\log^4 n)$ time;\label{it:rlz}
        \item given $i,j\in [1\dd n]$ with $i\le j$, compute $\CR(X[i\dd j])$, in $\Oh(z \log^4 n)$ time.\label{it:extract}
    \end{enumerate}
    Moreover, $\CR(X)$ can be constructed:
    \begin{enumerate}[label=\textrm{(\alph*)},resume]
        \item in $\Oh(f \log^2 n)$ time given an $f$-phrase LZ-like representation of $X$ or $\rev{X}$;\label{it:fromLZ}
        \item in $\Oh(z\log^4 n)$ time given $\CR(X[1\dd i))$ and $\CR(X[i\dd n])$ for some $i\in [1\dd n]$.\label{it:concat}
    \end{enumerate}
\end{proposition}

\begin{restatable}[Greedy alignment]{definition}{defgreedy}\label{def:greedy_alignment}
We say that an alignment $\A$ of two strings $X, Y\in \Sigma^*$ is \emph{greedy} if  $X[x] \ne Y[y]$ holds for every $(x,y)\in \brkp(\A) \cap ([1\dd |X|]\times [1\dd |Y|])$.
Given $k\ge 0$, we denote by $\ga_k(X,Y)$ the set of all greedy alignments $\A$ of $X,Y$
satisfying $\cost(\A)\le k$.
\end{restatable}

For strings $X,Y\in \Sigma^*$ and an integer $k\ge \ed(X,Y)$, we define a set \[\mtch_k(X,Y) = \bigcap_{\A \in \ga_k(X,Y)} \mtch_{X,Y}(\A)\] of \emph{common matches} of all alignments $\A\in \ga_k(X,Y)$;
note that it forms a non-crossing matching of~${X,Y}$.

\begin{restatable}{definition}{defnoncrossing}
Let $M$ be a non-crossing matching of strings $X,Y\in \Sigma^*$.
We define $X^M,Y^M$ to be the strings obtained from $X,Y$ by replacing $X[x]$ and $Y[y]$
with $\# \notin \Sigma$ for every $(x,y)\in M$. 
We refer to $\#$ as a \emph{dummy symbol} and to maximal blocks of $\#$'s as \emph{dummy segments}.
\end{restatable}

Additionally, for a string $Z \in (\Sigma \cup \#)^*$, we define $\num(Z)$ as a string obtained from $Z$ by replacing the $i$th leftmost occurrence of $\#$ in it with a unique dummy symbol $\#_i \notin \Sigma$. 

\begin{restatable}{lemma}{lmmasking}\label{lm:masking_does_not_change_ga}
Consider strings $X,Y\in \Sigma^*$, an integer $k\ge \ed(X,Y)$, and a set  $M\sub \mtch_k(X,Y)$.
Then, $\ed(X,Y)=\ed(\num(X^M),\num(Y^M))$ and $\mtch_k(X,Y)=\mtch_k(\num(X^M),\num(Y^M))$.
\end{restatable}

\begin{proposition}\label{prop:rank}
Consider a string $S\in (\Sigma\cup\{\#\})^n$ with $s$ dummy segments.
Given the sorted list of dummy segments in $S$, one can in $\Oh(s)$ time construct a data structure $\RS_\#(S)$ supporting the following queries in $\Oh(\log s)$ time: 
\begin{enumerate}
  \item $\mathbf\rank_\#(S,i)$: Given $i\in [1\dd n+1]$, return $|\{i' \in [1\dd i) : S[i'] = \#\}|$.
 \item $\mathbf\select_\#(S,j)$: Given $j\in [1\dd \rank_\#(S,n)]$, return the $j$th smallest element of $\{i \in [1\dd n] : S[i] = \#\}$.
\end{enumerate}
\end{proposition}

\begin{definition}\label{def:masked_encoding}
For a non-crossing matching $M$ of strings $X,Y\in \Sigma^*$
we set (cf.~\cref{prp:RLSLP}):  \[\Enc^{M}(X,Y):=\left(\CR(X^MY^M), \RS_\#(X^M), \RS_\#(Y^M) \right).\]
\end{definition}

\begin{lemma}\label{lm:eLCE}
  Let $X' = \num(X^M)$ and $Y' = \num(Y^M)$ for a non-crossing matching $M$ of strings $X,Y\in \Sigma^{\le n}$.
  The encoding $\Enc^{M}(X,Y)$ allows answering $\LCE$ queries
  on the suffixes of $X',Y'$ and on the suffixes of $\rev{X'},\rev{Y'}$
  in $\Oh(\log n)$ time.
\end{lemma}

\begin{corollary}\label{cor:ED}
Given an integer $k> 0$ and the encoding $\Enc^{M}(X,Y)$ for a non-crossing matching $M$ of strings $X,Y\in \Sigma^{\le n}$, one can in $\Oh(k^2\log n)$ time compute a integer $d\in [0\dd k+1]$ such that
\[ d = \begin{cases}
  \ed(X,Y) & \text{if }\ed(X,Y)\le k\text{ and }M\sub \mtch_k(X,Y),\\
  k+1 & \text{if }\ed(X,Y)>k.
\end{cases}\]
\end{corollary}

\begin{definition}\label{def:greedy_encoding}
	For strings $X,Y\in \Sigma^*$ and an integer $k$, we define the \emph{greedy encoding} 
	\[\gr_k(X,Y)=\begin{cases}
	  \Enc^{\mtch_k(X,Y)}(X,Y) & \text{if }k\ge \ed(X,Y),\\
	  \bot & \text{otherwise.}\end{cases}\]
\end{definition}

\begin{restatable}{lemma}{lmgreedyalg}\label{lm:greedyalg}
	For all $X,Y\in \Sigma^*$ and $k\in \Zp$, the set $\brkp_k(X,Y) = \hspace{-.4cm}  \bigcup\limits_{\A \in \ga_k(X,Y)} \hspace{-.4cm} \brkp(\A)$ is of size~$\Oh(k^5)$.
\end{restatable}

\begin{claim}\label{claim:LMS}
Given two strings $U,V$, and a data structure of size $s$ that can answer the $\LCE$ queries on the suffixes of $\rev{U}, \rev{V}$ in $t$ time. We can build in $\Oh(k^2 t)$ time a data structure that occupies $\Oh(k^2)$ space and can retrieve $\min(k+1,\ed(U[u\dd], V[v\dd]))$ in $\Oh(\log n)$ time.
\end{claim}

\begin{definition}[Quasi-greedy alignment]\label{def:quasi_greedy_alignment}
  We say that an alignment $\A$ of two strings $X, Y\in \Sigma^*$ is \emph{quasi-greedy} if it satisfies at least one of the following symmetric conditions:
  \begin{itemize}
    \item there exists $\delta \in [1\dd |X|+1]$ such that $(\delta,1)\in \A$ and $X[x] \neq Y[y]$ holds for every $(x,y) \in \brkp(\A) \cap ([\delta\dd|X|]\times [1\dd |Y|])$;
    \item there exists $\delta \in [1\dd |Y|+1]$ such that $(1,\delta)\in \A$ and $X[x] \neq Y[y]$ holds for every $(x,y) \in \brkp(\A) \cap ([1\dd|X|]\times [\delta\dd |Y|])$;
  \end{itemize}
Given $k\ge 0$, we denote by $\qga_k(X,Y)$ the set of all quasi-greedy alignments $\A$ of $X,Y$ with $\cost(\A)\le k$.
\end{definition}

For strings $X,Y\in \Sigma^*$ and an integer $k\ge \ed(X,Y)$, we define a set \[\qmtch_k(X,Y) = \bigcap_{\A \in \qga_k(X,Y)} \mtch_{X,Y}(\A)\] of \emph{common matches} of all alignments $\A\in \qga_k(X,Y)$.

\begin{definition}
  For strings $X,Y\in \Sigma^*$ and an integer $k$, we define the \emph{quasi-greedy encoding} 
  \[\qgr_k(X, Y) = \begin{cases} \Enc^{\qmtch_k(X,Y)}(X,Y)&\text{if }\ed(X,Y)\le k,\\
    \bot &\text{otherwise.}\end{cases}\]
\end{definition}

\begin{corollary}\label{cor:qgr_to_gr}
  Consider strings $X,Y \in \Sigma^{\le n}$. Define $X' = \$_1 X$ and $Y' = \$_2 Y$, where $\$_1 \neq \$_2$ are special symbols not in $\Sigma$. Let $M' = \mtch_{k+1}(X',Y')$ and $M = \qmtch_k(X,Y)$. The following properties hold:
\begin{enumerate}[label=\textrm{(\alph*)}]
\item Given the dummy segments for one of the strings $X^{M}, (X')^{M'}$, the dummy segments for the other string can be constructed in $\Oh(k)$ time and space;\label{it:dummy} 
\item  Given one of the encodings $\qgr_k(X, Y), \gr_{k+1}(X', Y')$, the other encoding can be constructed in $\Oh(k^2 \log^4 n)$ time and space;\label{it:encodings}
\item The quasi-greedy encoding $\qgr_k(X, Y)$ occupies $\Oh(k^2 \log^4 n)$ space. \label{it:qga_space} 
\end{enumerate}
\end{corollary}


